<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>商品分类</span><el-button type="primary" size="small" @click="showDialog=true">新增分类</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="分类名称"/><el-table-column prop="sort" label="排序" width="100"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="showDialog" :title="form.id?'编辑分类':'新增分类'" width="500px"><el-form :model="form" label-width="80px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({id:null,name:'',sort:0,status:1});const loadList=async()=>{const res=await request({url:'/categories'});list.value=res.data?.list||res.data||[]};const edit=(row)=>{Object.assign(form,row);showDialog.value=true};const submit=async()=>{if(form.id){await request({url:`/categories/${form.id}`,method:'put',data:form})}else{await request({url:'/categories',method:'post',data:form})}ElMessage.success('保存成功');showDialog.value=false;loadList()};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/categories/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};onMounted(()=>loadList())</script>
